from pathlib import Path
p=Path('projects/midterm_rag_20261104/notes/total.md')
s=p.read_text(encoding='utf-8'); extra=['汇报主要分为系统设计、实验结果、问题分析以及下一阶段计划四部分。','例如用户询问洗衣机容量时，系统应当找到对应型号的资料，而不是仅凭通用知识生成一个数字。','前端提供资料导入与问答界面，后端负责文档处理、检索和会话编排。SQLite 保存业务数据，语义模式可以使用 FAISS 加速检索。','字符检索强调字面匹配，语义检索则利用预训练模型表示文本。两种方式适用情况不同，需要结合片段结构和问题类型评估。','需要注意，有来源并不天然代表回答正确。我们还要检查来源是否包含问题所需的具体事实，以及生成答案是否忠于来源。','题目中既有能够从资料查到答案的题，也有资料没有提供答案的题，还有需要转人工的场景。指标分别衡量检索、回答状态和延迟，不能互相替代。','这里关键词命中只是自动评估方法，无法完全衡量一段回答是否完整、忠实。我们因此还需要人工检查具体答案和错误案例。','另外，在线方案有网络请求和生成过程，离线方案返回原文，因此延迟差异也不只是检索耗时。实验结果不能推广为所有模型或所有语料的结论。','例如系统把价格问题匹配到安装温度，虽然同属冰箱资料，却没有回答价格。这说明相似度高不等于证据充分，需要进一步识别问题要求的属性。','除了提高准确率，我们还要关注不同型号的隔离和无答案场景的可靠拒答，并将每次改动与固定测试集对照，记录具体失败案例。','具体的模型训练相关工作会按项目文档实际实现说明，不把规则整理或使用预训练模型描述为已经完成参数微调。']
parts=s.split('\n\n---\n\n');p.write_text('\n\n---\n\n'.join(v+'\n\n'+extra[i] for i,v in enumerate(parts)),encoding='utf-8');Path('projects/midterm_rag_20261104/逐页讲稿_完整版.md').write_text('# 期中汇报逐页讲稿\n\n'+p.read_text(encoding='utf-8'),encoding='utf-8')
